
/**
 * @fileoverview ALEXANDROV'S PSYCHOMATRIX — Complete Line & Column Interpretations
 * Quantitative Scale for All Lines, Columns, and Diagonals
 */

// ─────────────────────────────────────────────────────────────────────────────
// TYPES
// ─────────────────────────────────────────────────────────────────────────────

export type LineScaleLevel =
  | 'absent'     // 0 digits
  | 'very-weak'  // 1 digit
  | 'norm'       // 2 digits
  | 'special'    // 3 digits
  | 'strong'     // 4 digits
  | 'dominant'   // 5 digits
  | 'overload';  // 6+ digits

export interface LineCountInterpretation {
  count: number;
  label: string;
  verbatim: string;
  scale: LineScaleLevel;
}

export interface PsychomatrixLineInterpretation {
  id: string;
  type: 'row' | 'column' | 'diagonal';
  digits: number[];
  name: string;
  quality: string;
  captionNote: string;
  levels: LineCountInterpretation[];
  orthodox?: string;
  esoteric?: string;
  transmutation?: string;
}

// ─────────────────────────────────────────────────────────────────────────────
// HELPER: resolve interpretation from a raw line digit-count total
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Returns the correct LineCountInterpretation for a given line total.
 * Rectification Turn 7: If total >= 6, return a combination of 5+ and 6+ meanings.
 */
export function getLineLevel(
  lineId: string,
  totalDigits: number
): LineCountInterpretation | undefined {
  const lineDef = PSYCHOMATRIX_LINE_INTERPRETATIONS.find(l => l.id === lineId);
  if (!lineDef) return undefined;

  const exactLevel = lineDef.levels.find(l => l.count === totalDigits);
  if (exactLevel && totalDigits < 6) return exactLevel;

  // Handle counts not explicitly in the array (e.g., 7, 8, 9)
  if (totalDigits >= 6) {
    const dominant = lineDef.levels.find(l => l.count === 5);
    const overload = lineDef.levels.find(l => l.count === 6);
    if (dominant && overload) {
      return {
        count: totalDigits,
        label: overload.label,
        scale: 'overload',
        verbatim: dominant.verbatim + '\n\n' + overload.verbatim
      };
    }
    return overload;
  }

  // Fallback for intermediate values (like 1, 3 for lines that jump)
  return (
    lineDef.levels.find(l => l.count === Math.min(totalDigits, 6)) ??
    lineDef.levels[lineDef.levels.length - 1]
  );
}

export function computeLineTotal(
  lineDigits: number[],
  counts: Record<number, number>
): number {
  return lineDigits.reduce((sum, d) => sum + (counts[d] || 0), 0);
}

